const ch = await conn.createChannel();
await ch.assertExchange('dlx', 'direct', { durable: true });
await ch.assertQueue('orders.dlq', { durable: true });
await ch.bindQueue('orders.dlq', 'dlx', 'failed');
await ch.assertQueue('orders', { durable: true, arguments: {
  'x-dead-letter-exchange': 'dlx', 'x-dead-letter-routing-key': 'failed' } });
await ch.consume('orders', msg => {
  try { handle(msg); ch.ack(msg); }
  catch (e) { ch.nack(msg, false, false); }   // requeue=false -> broker dead-letters
});

