const q = new Queue('orders', { connection });
await q.add('apply', payload, {
  attempts: 5,
  backoff: { type: 'exponential', delay: 1000 },
  removeOnFail: false,                       // keep the dead letter
});
const dead = await q.getFailed(0, 50);       // operator view of the failed set
